    var a = try Tensor.init(allocator, &.{3, 4});
    defer a.deinit();

    try a.fill(1.0);

    var b = try Tensor.init(allocator, &.{3, 4});
    defer b.deinit();

    try b.fill(2.0);

    // Összeadás
    try a.add(&b);

    // Minden elem most 3.0
    const val = try a.get(&.{0, 0});
    std.debug.print("Value: {}\n", .{val});
}
```

### Neurális Hálózat Layer

```zig
pub const LinearLayer = struct {
    weight: Tensor,
    bias: Tensor,

    pub fn init(allocator: Allocator, in_features: usize, out_features: usize) !LinearLayer {
        var weight = try Tensor.randomNormal(allocator, &.{in_features, out_features}, 0.0, 0.1, 42);
        var bias = try Tensor.zeros(allocator, &.{out_features});
        return .{ .weight = weight, .bias = bias };
    }

    pub fn forward(self: *const LinearLayer, input: *const Tensor, allocator: Allocator) !Tensor {
        // y = x * W + b
        var output = try Tensor.matmul(input, &self.weight, allocator);
        try output.add(&self.bias);
        return output;
    }

    pub fn deinit(self: *LinearLayer) void {
        self.weight.deinit();
        self.bias.deinit();
    }
};
```

